const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icons={menu:'M4 6h16 M4 12h16 M4 18h16',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',repost:'m4 8 3-3 3 3 M7 5v11h7 M20 16l-3 3-3-3 M17 19V8h-7',share:'M12 16V3 m-4 4 4-4 4 4 M5 12v9h14v-9',news:'M4 3h13v18H4z M17 7h4v14h-4 M7 7h7 M7 11h7 M7 15h3 M7 18h7',x:'M5 3h4l10 18h-4z M19 3 5 21',instagram:'M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17.5 6.5h.01',send:'m22 2-7 20-4-9-9-4 20-7 M22 2 11 13',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 6l2-2 3 1 3-3 3 3 3-1 2 2-1 3 3 3-3 3 1 3-2 2-3-1-3 3-3-3-3 1-2-2 1-3-3-3 3-3z'};
const I=n=>icons[n]?`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]}"/></svg>`:baseIcon(n);
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=(n,d=2)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const C=n=>Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n||0);
const detailP=n=>n<.01?'<1':n>.99?'>99':N(n*100,1);
const P=n=>n<.01?'<1':n>.99?'>99':Math.round(n*100);
const T=t=>new Date(t).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});
const D=t=>new Date(t).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const ago=t=>{const sec=Math.max(0,(Date.now()-t)/1000);return sec<60?'now':sec<3600?Math.floor(sec/60)+'m':sec<86400?Math.floor(sec/3600)+'h':Math.floor(sec/86400)+'d';};
const B=(a,label,cls='button',attrs='')=>`<button type="button" class="${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const marketLookups=new Map();
const cats=['Trending','Live','Politics','Crypto','Sports','HardFi','Economy','Tech & AI','Culture','Geopolitics','Weather'];
const extra={posts:[],communityReady:false,postLikes:[],savedPosts:[],postVotes:[],proposals:[],ideaVotes:[],discussion:{},socialActivity:[],outbox:[],makerClaims:[],soundVolume:.34};
let s;try{s={...initialState(),...structuredClone(extra),...JSON.parse(localStorage.getItem('strato-odds-local')||'null')};}catch{s={...initialState(),...structuredClone(extra)};}
let events=[],allEvents=new Map(),meta={},news=[],page='markets',category='Trending',search='',sort='trending',watchOnly=false,limit=18,menuOpen=false,feedTab='for-you',leaderPeriod='month',leaderMetric='profit',portfolioTab='positions',rewardTab='overview',poolSearch='',selected=null,event=null,side='Yes',mode='buy',orderType='market',amount=25,limitPrice=50,spread=3,range='1d',tab='discussion',discussionSort='top',markerFilter='all',fullScale=false,history=[],book=null,publicTrades=[],chartLoading=false,heroHistory={},newsFilter='All',socket=null,heartbeat=null,socketRetry=null,bookBusy=false,request=0,pending=null,spinBusy=false,wheelAngle=0,focusedPost=null,xConfig={x:false},liveStatus='connecting',lastTick=0,showDepth=false;
const save=()=>{try{localStorage.setItem('strato-odds-local',JSON.stringify(s));}catch{notify('Storage is full. Export your portfolio to keep a copy.');}};
const byId=id=>allEvents.get(id)||events.find(e=>e.id===id);
const marketById=id=>[...allEvents.values()].flatMap(e=>e.markets).find(m=>m.id===id);
const priceMap=()=>Object.fromEntries([...allEvents.values()].flatMap(e=>e.markets.flatMap(m=>[[m.id+'-Yes',m.yes],[m.id+'-No',1-m.yes]])));
const spins=()=>Math.max(0,Math.floor(s.predictions/10)-s.spinsUsed);
const avatar=(id,size='')=>{const p=person(id);return `<span class="avatar ${size} avatar-${p.index??0}" style="--avatar:${p.color}"><span>${E(p.initials)}</span></span>`;};
function picture(e,cls=''){const src=cachedImages[e.id]||e.image;return src?`<img class="market-image ${cls}" src="${E(src)}" alt="" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><span class="market-image monogram ${cls}" hidden>${E(e.monogram||e.category?.slice(0,2)||'ST')}</span>`:`<span class="market-image monogram ${cls}">${E(e.monogram||e.category?.slice(0,2)||'ST')}</span>`;}
const outcomeLabel=(m,which)=>m?.outcomes?.[which==='Yes'?0:1]||which;
function notify(message){const e=document.createElement('div');e.className='toast';e.innerHTML=I('check')+'<span>'+E(message.replace(/\bdemo[- ]?/gi,'').replace(/\bpaper /gi,''))+'</span>';$('#toast-root').append(e);setTimeout(()=>e.remove(),4200);}
function chime(kind='trade'){if(s.sound)playSound(kind,s.soundVolume);}
function updateAccount(){save();const el=$('#balance-value');if(el)el.textContent=N(s.balance);}
function header(){return `<header class="site-header"><div class="header-inner"><a href="#markets" class="brand" aria-label="STRATO Odds home"><img src="assets/odds.png" alt="STRATO Odds"></a><label class="search"><span>${I('search')}</span><input type="search" id="search" aria-label="Search markets" placeholder="Search markets" value="${E(search)}"><kbd>/</kbd></label><div class="header-actions"><a href="#portfolio" class="header-balance"><span>Balance</span><strong>$<b id="balance-value">${N(s.balance)}</b></strong></a><a href="#rewards" class="header-rewards" aria-label="Rewards${spins()?' · '+spins()+' spins ready':''}">${I('gift')}<span>Rewards</span>${spins()?`<b>${spins()}</b>`:''}</a>${B('fund','Add funds','button header-fund')}${B('sound',I(s.sound?'volume':'mute'),'icon-button header-sound',`aria-label="${s.sound?'Mute sounds':'Turn on sounds'}"`)}${B('menu',I('menu'),'menu-button',`aria-label="Open navigation" aria-expanded="${menuOpen}"`)}</div></div></header><nav class="topic-nav" aria-label="Topics"><div>${cats.map(c=>`<a href="#markets/${encodeURIComponent(c)}" class="${page==='markets'&&category===c?'active':''}">${c==='Trending'?I('trend'):c==='Live'?'<i class="live-dot"></i>':''}${c}</a>`).join('')}<a href="#social" class="social-nav ${page==='social'?'active':''}">${I('users')} Social</a></div></nav>${menuOpen?navigation():''}`;}
function navigation(){return `<div class="menu-shade" data-action="menu-close"></div><aside class="navigation-menu" aria-label="Main menu"><div class="menu-account">${avatar('you')}<div><b>Your account</b><small>${N(s.xp,0)} XP · ${s.xp<1000?'Forecaster':'Market insider'}</small></div>${B('menu-close',I('close'),'icon-button','aria-label="Close navigation"')}</div>${[['markets','grid','Markets'],['social','users','Social & news'],['pools','droplet','Liquidity pools'],['traders','trophy','Traders & leaderboards'],['rewards','gift','Rewards'],['portfolio','wallet','Portfolio']].map(([v,i,l])=>`<a href="#${v}" class="${page===v?'active':''}">${I(i)}<span>${l}</span>${v==='rewards'&&spins()?`<b class="count">${spins()}</b>`:I('chevron')}</a>`).join('')}<div class="menu-bottom">${B('connections',I('link')+' Social connections','text-button')}${B('settings',I('settings')+' Settings','text-button')}${B('about',I('info')+' About this build','text-button')}</div></aside>`;}
function footer(){return `<footer class="site-footer"><div class="footer-inner"><div class="footer-brand"><a href="#markets"><img src="assets/odds.png" alt="STRATO Odds"></a><div class="footer-socials"><a href="https://x.com/strato_net" target="_blank" rel="noopener" aria-label="STRATO on X">${I('x')}</a><a href="https://t.me/strato_net" target="_blank" rel="noopener" aria-label="STRATO on Telegram">${I('send')}</a><a href="https://strato.nexus/" target="_blank" rel="noopener" aria-label="STRATO website">${I('globe')}</a></div></div><div><h3>Explore</h3><a href="#markets">Markets</a><a href="#markets/Live">Live markets</a><a href="#social/news">News</a><a href="#social/ideas">Market ideas</a></div><div><h3>Participate</h3><a href="#pools">Add liquidity</a><a href="#rewards">Rewards</a><a href="#traders">Leaderboards</a><a href="#social">Community</a></div><div><h3>STRATO</h3><a href="https://app.strato.nexus/dashboard/" target="_blank" rel="noopener">STRATO App ${I('external')}</a><a href="https://docs.strato.nexus/" target="_blank" rel="noopener">Documentation ${I('external')}</a>${B('help','How it works','footer-button')}${B('connections','Social connections','footer-button')}</div></div><div class="footer-bottom"><span>© 2026 STRATO Odds</span><div>${B('about','About','footer-button')}${B('rules-help','Market rules','footer-button')}${B('settings','Settings','footer-button')}</div><span class="footer-status"><i class="live-dot"></i> ${meta.status==='live'?'Markets connected':'Market snapshot'}</span></div></footer>`;}
function render(){
 const focus=document.activeElement?.id,pos=document.activeElement?.selectionStart;
 document.title=(page==='market'&&event?event.title:page==='social'?'Social':page[0].toUpperCase()+page.slice(1))+' · STRATO Odds';
 $('#app').innerHTML=header()+`<main id="main">${page==='markets'?marketsPage():page==='market'?marketPage():page==='social'?socialPage():page==='traders'?tradersPage():page==='rewards'?rewardsPage():page==='pools'?poolsPage():portfolioPage()}</main>`+footer();
 if(focus&&$('#'+focus)){const el=$('#'+focus);el.focus();try{el.setSelectionRange(pos,pos);}catch{}}
 if(page==='market'){paintChart();paintBook();paintAsset();}
}
function renderMain(){render();}
function filterMarkets(){let list=events.filter(e=>(category==='Trending'||category==='Live'?(category!=='Live'||(new Date(e.end).getTime()>Date.now()&&new Date(e.end).getTime()<Date.now()+86400000)):e.category===category)&&(!watchOnly||s.watchlist.includes(e.id))&&(!search||(e.title+' '+e.category+' '+e.markets.map(m=>m.question).join(' ')).toLowerCase().includes(search.toLowerCase())));if(sort==='volume')list.sort((a,b)=>(b.volume24||0)-(a.volume24||0));if(sort==='closing')list.sort((a,b)=>new Date(a.end)-new Date(b.end));if(sort==='new')list.sort((a,b)=>(b.source==='STRATO concept')-(a.source==='STRATO concept'));return list;}
function card(e){const ms=[...e.markets].sort((a,b)=>b.yes-a.yes),m=ms[0],camp=campaignFor(e),live=new Date(e.end).getTime()>Date.now()&&new Date(e.end).getTime()<Date.now()+3600000;return `<article class="market-card"><div class="market-card-top">${picture(e)}<a href="#market/${e.id}/${m.id}" class="card-question">${E(e.title)}</a>${B('watch',I('bookmark'),'icon-button bookmark '+(s.watchlist.includes(e.id)?'saved':''),`data-id="${e.id}" aria-label="Save ${E(e.title)}"`)}</div>${ms.length>1?`<div class="card-outcomes">${ms.slice(0,2).map(m=>`<div><a href="#market/${e.id}/${m.id}">${E(m.label)}</a><strong data-prob="${m.id}">${P(m.yes)}%</strong>${B('open-trade','Yes','choice yes',`data-e="${e.id}" data-m="${m.id}" data-side="Yes"`)}${B('open-trade','No','choice no',`data-e="${e.id}" data-m="${m.id}" data-side="No"`)}</div>`).join('')}</div>`:`<div class="card-chance"><strong data-prob="${m.id}">${P(m.yes)}<small>%</small></strong><span>chance</span></div><div class="card-trade">${B('open-trade',`${E(outcomeLabel(m,'Yes'))} <b data-price="${m.id}-Yes">${N(m.yes*100,1)}¢</b>`,'yes',`data-e="${e.id}" data-m="${m.id}" data-side="Yes"`)}${B('open-trade',`${E(outcomeLabel(m,'No'))} <b data-price="${m.id}-No">${N((1-m.yes)*100,1)}¢</b>`,'no',`data-e="${e.id}" data-m="${m.id}" data-side="No"`)}</div>`}<div class="card-foot"><div class="card-meta"><span class="card-date" title="${E(new Date(e.end).toLocaleString())}">${I('clock')}${Number.isFinite(Date.parse(e.end))?D(e.end):'Date pending'}</span><span class="card-volume">${Number(e.volume)>0?e.source==='Kalshi'?C(e.volume)+' contracts':'$'+C(e.volume)+' vol.':'Vol. —'}</span><span class="card-live-slot">${live?'<span class="card-live-badge"><i class="live-dot"></i> Live</span>':''}</span></div><a href="#market/${e.id}/${m.id}" class="earn-label">${I('gift')} Earn rewards ${I('chevron')}</a></div></article>`;}
function hero(){const first=events.find(e=>e.category==='Politics'&&e.title.includes('House')&&e.source==='Polymarket')||events[0];const second=events.find(e=>e.category==='HardFi'&&e.title.toLowerCase().includes('gold')&&e.source==='Polymarket')||events.find(e=>e.category==='Crypto');return `<section class="hero-grid">${[first,second].filter(Boolean).map((e,i)=>{if(i===1&&news.length)return featureNews(news[0]);const ms=[...e.markets].sort((a,b)=>b.yes-a.yes);return `<article class="feature-market ${i?'secondary-feature':''}"><div class="feature-title"><span>${e.category==='Politics'?'2026 MIDTERMS':'HARD ASSETS'}</span><a href="#market/${e.id}/${ms[0].id}">${I('external')}</a></div><div class="feature-heading">${picture(e,'large')}<a href="#market/${e.id}/${ms[0].id}"><h1>${E(e.title)}</h1></a></div><div class="feature-body"><div class="feature-outcomes">${ms.slice(0,2).map((m,j)=>`<a href="#market/${e.id}/${m.id}"><span class="outcome-dot dot-${j}"></span><span>${E(m.label)}</span><strong data-prob="${m.id}">${P(m.yes)}%</strong></a>`).join('')}</div><div class="hero-chart" id="hero-chart-${i}">${heroHistory[e.id]?sparkSVG(heroHistory[e.id]):`<div class="feature-probability"><span>${E(ms[0].label)}</span><strong>${P(ms[0].yes)}%</strong><div><i style="width:${ms[0].yes*100}%"></i></div></div>`}</div></div><div class="feature-foot"><span>${e.volume?'$'+C(e.volume)+' volume':D(e.end)}</span><a href="#market/${e.id}/${ms[0].id}">View market ${I('arrow')}</a></div></article>`;}).join('')}</section>`;}
function featureNews(n){return `<article class="feature-market feature-news secondary-feature"><div class="feature-title"><span>THE BRIEFING</span><span>${E(n.publisher)} · ${ago(n.time)}</span></div><button class="feature-news-art" data-action="news" data-id="${n.id}" ${n.image?`style="background-image:url('${E(n.image)}')"`:''}>${!n.image?`<span>${E(n.publisher==='BBC'?'WORLD NEWS':n.publisher.toUpperCase())}</span>`:''}</button><button class="feature-news-title" data-action="news" data-id="${n.id}">${E(n.title)}</button><div class="feature-foot"><span>${E(n.category)}</span>${B('news','Read story '+I('arrow'),'text-link',`data-id="${n.id}"`)}</div></article>`;}
function followingStrip(){const entries=s.socialActivity.slice(0,4);const picks=entries.length?entries:events.slice(0,4).map((e,i)=>({person:people[i].id,eventId:e.id,marketId:e.markets[0].id,side:i%2?'No':'Yes',price:i%2?1-e.markets[0].yes:e.markets[0].yes,amount:150+i*50,time:Date.now()-i*180000}));return `<section class="market-pulse-strip"><a href="#social/following" class="pulse-title">${I('bolt')} Market pulse</a><div>${picks.map(a=>{const p=person(a.person),e=byId(a.eventId);return e?`<a href="#market/${e.id}/${a.marketId}" class="pulse-tick">${avatar(p.id,'tiny')}<b>${p.name}</b><span class="${a.side==='No'?'red':'green'}">${a.side.toUpperCase()}</span><span>${E(e.title).slice(0,43)}${e.title.length>43?'…':''}</span></a>`:'';}).join('')}</div></section>`;}
function marketsPage(){const list=filterMarkets();const featured=!search&&!watchOnly&&category==='Trending';return `<div class="container markets-container">${featured?hero()+followingStrip():''}<section class="discovery"><div class="section-heading"><div><h2>${watchOnly?'Watchlist':search?'Search results':category==='Trending'?'All markets':category==='Live'?'Live markets':category}</h2><span class="section-count">${list.length} markets</span></div><div class="market-tools">${B('watch-filter',I('bookmark'),'filter-button '+(watchOnly?'selected':''),`aria-label="Show watchlist" aria-pressed="${watchOnly}"`)}<select id="sort" aria-label="Sort markets">${[['trending','Trending'],['volume','Volume'],['closing','Closing soon'],['new','New markets']].map(([v,t])=>`<option value="${v}" ${v===sort?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="market-grid">${list.slice(0,limit).map(card).join('')||empty('No matching markets','Try another topic or search.','clear-search','Clear filters')}</div>${list.length>limit?B('more','Show more markets '+I('down'),'button secondary load-more'):''}</section>${news.length?`<section class="briefing-section"><div class="section-heading"><h2>The briefing</h2><a href="#social/news" class="text-link">All news ${I('arrow')}</a></div><div class="news-grid">${news.slice(0,4).map(newsCard).join('')}</div></section>`:''}${featured?`<section class="participation-banner"><div>${I('gift')}<h2>Liquidity and rewards</h2></div><div><a href="#pools">Earn by adding liquidity ${I('arrow')}</a><a href="#rewards">Explore rewards ${I('arrow')}</a></div></section>`:''}</div>`;}
function newsCard(n){return `<article class="news-card"><button class="news-art tone-${n.category==='Crypto'?'crypto':n.category==='Economy'?'economy':'world'}" data-action="news" data-id="${n.id}" ${n.image?`style="background-image:linear-gradient(180deg,transparent,#001b7140),url('${E(n.image)}')"`:''}><span>${E(n.category.toUpperCase())}</span>${!n.image?`<strong>${n.publisher==='Federal Reserve'?'FED':n.publisher==='NASA'?'SPACE':n.category==='Crypto'?'₿':'WORLD'}</strong>`:''}</button><div class="news-source">${E(n.publisher)} <span>${ago(n.time)}</span></div><button class="news-headline" data-action="news" data-id="${n.id}">${E(n.title)}</button></article>`;}
function empty(title,text,action='',label=''){return `<div class="empty">${I('search')}<h3>${title}</h3><p>${text}</p>${action?B(action,label,'button secondary'):''}</div>`;}
function marketPage(){
 if(!event||!selected){const lookup=marketLookups.get(location.hash.split('/')[1]);return `<div class="container">${lookup&&!lookup.pending?empty(lookup.ended?'This market has ended':'Market unavailable',lookup.title||'Browse the latest open markets.')+`<div class="market-return"><a href="#markets/Live" class="button primary">Explore live markets ${I('arrow')}</a></div>`:empty('Finding this market…','The market catalog is loading.')}</div>`;}
 const m=selected,ms=[...event.markets].sort((a,b)=>b.yes-a.yes),camp=campaignFor(event),comments=getDiscussion();
 return `<div class="container detail-container"><div class="breadcrumb"><a href="#markets">Markets</a>${I('chevron')}<a href="#markets/${encodeURIComponent(event.category)}">${E(event.category)}</a></div><div class="market-layout"><section class="market-main"><div class="detail-title">${picture(event,'large')}<div><span class="detail-category">${E(event.category)}</span><h1>${E(event.title)}</h1></div>${B('watch',I('bookmark'),'icon-button bookmark '+(s.watchlist.includes(event.id)?'saved':''),`data-id="${event.id}" aria-label="Save market"`)}${B('share-market',I('share'),'icon-button','aria-label="Share market"')}</div><div class="detail-stats"><span>${I('trend')}${event.volume?event.source==='Kalshi'?C(event.volume)+' contracts':'$'+C(event.volume)+' volume':'USDST market'}</span><span>${I('clock')}${D(m.end)}</span>${B('rules',I('info')+' Rules','text-button')}${B('alert',I('bell')+' Alert','text-button')}<span class="live-indicator" id="live-status"><i class="live-dot"></i> ${liveStatus==='live'?'Live':'Connecting'}</span></div>${ms.length>1?`<div class="outcome-picker"><label>Outcome<select id="outcome" aria-label="Select outcome">${ms.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${E(x.label)} · ${P(x.yes)}%</option>`).join('')}</select></label></div>`:''}${assetMarkup(event)}<div class="chart-head"><div class="detail-probability"><strong id="detail-prob">${detailP(m.yes)}<small>%</small></strong><div><span>${E(outcomeLabel(m,'Yes'))} chance</span><small id="chart-change">${history.length>1?changeText():''}</small></div></div><div class="chart-actions">${B('marker-toggle',I('users'),'filter-button '+(markerFilter!=='off'?'selected':''),'aria-label="Trader chart markers"')}<select id="marker-filter" aria-label="Show chart entries"><option value="all" ${markerFilter==='all'?'selected':''}>Trader entries</option><option value="following" ${markerFilter==='following'?'selected':''}>Following</option><option value="mine" ${markerFilter==='mine'?'selected':''}>My entries</option><option value="off" ${markerFilter==='off'?'selected':''}>Hide entries</option></select></div></div><div class="chart-frame" id="chart-frame"><div id="chart-surface"></div><div id="chart-tooltip" class="chart-tooltip" hidden></div>${chartLoading?'<div class="chart-loading">Loading chart…</div>':''}</div><div class="chart-bottom"><span class="chart-legend"><i></i> ${E(outcomeLabel(m,'Yes'))}</span><div class="timeframes" aria-label="Chart timeframe">${[['live','Live'],['1h','1H'],['6h','6H'],['1d','1D'],['1w','1W'],['1m','1M'],['max','ALL']].map(([v,t])=>B('range',t,v===range?'active':'',`data-range="${v}" aria-pressed="${v===range}"`)).join('')}</div>${B('full-scale',fullScale?'0–100%':'Auto scale','text-button scale-button')}</div><div class="quote-update" id="quote-update" aria-label="Last market price update"></div>${followingOnMarket()}<div class="market-earn-banner"><span class="reward-emblem">${I('gift')}</span><div><b>Earn on this market</b><span><strong>${N(camp.daily,0)} USDST</strong> daily liquidity rewards</span></div>${B('earn-market','Add liquidity '+I('arrow'),'button secondary')}</div><nav class="detail-tabs" aria-label="Market details">${[['discussion',`Discussion <span>${comments.length}</span>`],['book','Order book'],['activity','Activity']].map(([v,l])=>B('detail-tab',l,tab===v?'active':'',`data-tab="${v}"`)).join('')}</nav><div id="detail-panel">${detailPanel()}</div></section><aside class="ticket-stack">${ticket()}<div class="ticket-market-summary"><span>${I('users')} Traders on this market</span><div>${people.slice(0,5).map(p=>avatar(p.id,'tiny')).join('')}<b>+${(String(m.id).length*13)%200+29}</b></div></div></aside></div><section class="related-section"><div class="section-heading"><h2>More in ${E(event.category)}</h2><a href="#markets/${encodeURIComponent(event.category)}" class="text-link">Explore ${I('arrow')}</a></div><div class="market-grid">${events.filter(e=>e.category===event.category&&e.id!==event.id).slice(0,3).map(card).join('')}</div></section></div>`;
}
function changeText(){if(history.length<2)return '';const delta=(selected.yes-(visibleHistory()[0]?.p??selected.yes))*100;return `${delta>=0?'+':''}${N(delta,1)} pts ${range==='live'?'live':range==='1d'?'today':'in range'}`;}
function getDiscussion(){if(!selected)return [];s.discussion[selected.id]??=initialComments(selected);const base=s.discussion[selected.id];return [...base].sort(discussionSort==='top'?(a,b)=>(b.likes||0)-(a.likes||0):(a,b)=>b.time-a.time);}
function followingOnMarket(){const ids=s.following.length?s.following.slice(0,3):['atlas','nova','leo'];return `<div class="trader-conviction"><div>${ids.map(id=>avatar(id,'tiny')).join('')}<span>${s.following.length?'People you follow':'Trader positions'}</span></div>${B('entries',`View entries ${I('chevron')}`,'text-button')}</div>`;}
function ticket(){const m=selected,p=s.positions.find(p=>p.key===m.id+'-'+side),deposit=s.liquidity.find(p=>p.marketId===m.id),camp=campaignFor(event),remaining=10-s.predictions%10;return `<section class="trade-ticket"><div class="ticket-tabs">${[['buy','Buy'],['sell','Sell'],['earn','Earn']].map(([v,l])=>B('mode',l,(mode===v?'active ':'')+(v==='earn'?'reward-tab':''),`data-mode="${v}"`)).join('')}<select id="order-type" aria-label="Order type" ${mode!=='buy'?'hidden':''}><option value="market" ${orderType==='market'?'selected':''}>Market</option><option value="limit" ${orderType==='limit'?'selected':''}>Limit</option></select></div><div class="ticket-body">${mode==='earn'?`<div class="earn-ticket-intro"><span class="reward-emblem">${I('droplet')}</span><h2>Add liquidity</h2><p>Fund both sides of this market and earn a share of the rewards.</p></div><div class="ticket-pool-reward"><span>Daily market rewards</span><b>${N(camp.daily,0)} USDST</b></div>`:`<div class="ticket-outcomes">${['Yes','No'].map(v=>B('side',`${E(outcomeLabel(m,v))}<strong data-ticket-price="${v}">${N((v==='Yes'?m.yes:1-m.yes)*100,1)}¢</strong>`,`${v.toLowerCase()} ${side===v?'selected':''}`,`data-side="${v}"`)).join('')}</div>`}${mode==='buy'&&orderType==='limit'?`<label class="field-label">Limit price<div class="limit-field"><input id="limit-price" type="number" aria-label="Limit price" value="${limitPrice}" min="1" max="99"><span>¢</span></div></label>`:''}<label class="field-label">${mode==='sell'?'Shares':'Amount'}<div class="amount-field"><span>${mode==='sell'?'':'$'}</span><input id="amount" aria-label="${mode==='sell'?'Shares to sell':'Amount'}" type="number" inputmode="decimal" value="${amount}" min="0.01" step="any"><small>${mode==='sell'?'shares':'USDST'}</small></div></label><div class="amount-presets">${(mode==='sell'?[.25,.5,1]:[10,50,100]).map(n=>B('preset',mode==='sell'?n*100+'%':'$'+n,'',`data-n="${n}"`)).join('')}${mode!=='sell'?B('max','Max'):''}</div><p class="available">${mode==='sell'?`${N(p?.shares||0)} shares available`:`Balance $${N(s.balance)}`}</p>${mode==='earn'?`<details class="quote-settings"><summary>Liquidity settings ${I('down')}</summary><label>Quote spread <span id="spread-label">${spread}¢</span><input id="spread" type="range" min="1" max="10" step="1" value="${spread}"></label><p>Keep both sides within ${camp.maxSpread}¢ to qualify for rewards.</p></details>`:''}<div id="ticket-calculation">${ticketCalculation()}</div>${B('review',mode==='earn'?'Add liquidity':mode==='sell'?'Sell '+E(outcomeLabel(m,side)):orderType==='limit'?'Place limit order':'Buy '+E(outcomeLabel(m,side)),'button primary trade-button '+(mode==='earn'?'reward-cta':''))}${mode==='earn'&&deposit?B('withdraw','Withdraw $'+N(deposit.amount),'text-button withdraw-button',`data-m="${m.id}"`):''}</div><a class="ticket-wheel-progress" href="#rewards"><span class="wheel-mini">${I('gift')}</span><div><b>${spins()?'Your reward spin is ready':`${remaining} ${remaining===1?'prediction':'predictions'} to your next spin`}</b><span class="progress"><i style="width:${spins()?100:s.predictions%10*10}%"></i></span></div>${I('chevron')}</a></section>`;}
function ticketCalculation(){const m=selected;if(!m)return '';const price=mode==='buy'&&orderType==='limit'?limitPrice/100:side==='Yes'?m.yes:1-m.yes,n=Number(amount)||0;if(mode==='sell')return `<div class="ticket-total"><span>You receive</span><b>$${N(n*price)}</b></div>`;if(mode==='earn'){const camp=campaignFor(event),existing=s.liquidity.find(p=>p.marketId===m.id)?.amount||0,share=(n+existing)/(camp.baseLiquidity+n+existing);return `<div class="calculation-row"><span>Your pool share</span><b>${N(share*100)}%</b></div><div class="ticket-total"><span>Estimated rewards / day</span><b>$${N(camp.daily*share*(spread<=camp.maxSpread?Math.min(1,3/spread):0))}</b></div>`;}return `<div class="calculation-row"><span>${orderType==='limit'?'Shares at limit':'Shares'}</span><b>${N(n/price)}</b></div><div class="ticket-total"><span>To win</span><b>$${N(n/price)}</b></div>`;}
function detailPanel(){if(tab==='book')return `<div class="book-panel"><div class="book-heading"><h3>Order book</h3><div>${B('depth-toggle',showDepth?'Table':'Depth','filter-button')}${B('refresh-book',I('refresh'),'icon-button','aria-label="Refresh order book"')}</div></div><div id="book-surface"></div></div>`;if(tab==='activity')return `<div class="activity-panel"><div class="section-heading compact-heading"><h3>Recent trades</h3><span id="trade-updated">${lastTick?T(lastTick):''}</span></div><div id="trades-surface">${tradesMarkup()}</div></div>`;return `<div class="discussion-panel"><form id="discussion-form" class="discussion-composer">${avatar('you','small')}<div><textarea name="text" id="discussion-text" aria-label="Write a comment" placeholder="What’s your view?" required maxlength="2000"></textarea><div><span>${mode==='sell'?'':s.positions.some(p=>p.marketId===selected.id)?'Position holder':''}</span><button class="button primary small-button" type="submit">Post ${I('send')}</button></div></div></form><div class="discussion-toolbar"><h3>Community discussion</h3><select id="discussion-sort" aria-label="Sort discussion"><option value="top" ${discussionSort==='top'?'selected':''}>Top comments</option><option value="new" ${discussionSort==='new'?'selected':''}>Newest</option></select></div>${getDiscussion().map(c=>commentMarkup(c)).join('')}</div>`;}
function commentMarkup(c,small=false){const p=person(c.person);return `<article class="comment ${small?'small-comment':''}"><button class="avatar-button" data-action="profile" data-id="${p.id}" aria-label="View ${E(p.name)}">${avatar(p.id,'small')}</button><div class="comment-content"><div class="comment-meta"><button data-action="profile" data-id="${p.id}" class="name-button">${E(p.name)}</button>${c.side?`<span class="position-tag ${c.side.toLowerCase()}">${c.side.toUpperCase()}</span>`:''}<time>${ago(c.time)}</time></div><p>${E(c.text)}</p><div class="comment-actions">${B('comment-like',I('heart')+' '+(c.likes||0),'text-button '+(s.postLikes.includes(c.id)?'liked':''),`data-id="${c.id}"`)}${B('reply','Reply','text-button',`data-id="${c.id}"`)}</div>${(c.replies||[]).map(r=>`<div class="comment-reply">${avatar(r.person,'tiny')}<div><b>${E(person(r.person).name)}</b><p>${E(r.text)}</p></div></div>`).join('')}</div></article>`;}
function tradesMarkup(){const own=s.trades.filter(t=>t.marketId===selected?.id&&['buy','sell'].includes(t.type)).slice(0,5);return `<div class="trade-table-heading"><span>Trader</span><span>Action</span><span>Price</span><span>Amount</span><span>Time</span></div>${own.map(t=>`<div class="trade-table-row"><span>${avatar('you','tiny')}You</span><span class="${t.side==='Yes'?'green':'red'}">${t.type==='buy'?'Buy':'Sell'} ${t.side}</span><b>${N(t.price*100,1)}¢</b><span>$${N(t.type==='sell'?t.proceeds:t.amount)}</span><time>${T(t.time)}</time></div>`).join('')}${publicTrades.slice(0,18).map(t=>`<div class="trade-table-row"><span><i class="wallet-avatar">${I('wallet')}</i>${E(t.proxyWallet?.slice(0,6)||t.proxy_wallet?.slice(0,6)||'Trader')}…</span><span class="${t.side==='BUY'?'green':'red'}">${t.side==='BUY'?'Buy':'Sell'} ${E(t.outcome)}</span><b>${N(t.price*100,1)}¢</b><span>$${N(t.price*t.size)}</span><time>${T(t.timestamp*1000)}</time></div>`).join('')}${!own.length&&!publicTrades.length?'<div class="quiet-empty">Trades will appear here as they happen.</div>':''}`;}
function paintBook(){const surface=$('#book-surface');if(!surface)return;if(!book){surface.innerHTML='<div class="quiet-empty">Waiting for the order book…</div>';return;}let bids=[...(book.bids||[])].map(x=>({price:+x.price,size:+x.size})).sort((a,b)=>b.price-a.price),asks=[...(book.asks||[])].map(x=>({price:+x.price,size:+x.size})).sort((a,b)=>a.price-b.price);const lp=s.liquidity.find(p=>p.marketId===selected.id);if(lp){const delta=(lp.spread||3)/200;bids.push({price:Math.max(.001,selected.yes-delta),size:lp.amount/2/Math.max(.001,selected.yes-delta),you:true});asks.push({price:Math.min(.999,selected.yes+delta),size:lp.amount/2/Math.min(.999,selected.yes+delta),you:true});bids.sort((a,b)=>b.price-a.price);asks.sort((a,b)=>a.price-b.price);}const max=Math.max(1,...bids.slice(0,8).map(x=>x.size),...asks.slice(0,8).map(x=>x.size));const row=(x,kind)=>`<button class="order-row ${kind} ${x.you?'your-quote':''}" data-action="book-price" data-price="${x.price}" style="--depth:${Math.max(2,x.size/max*100)}%"><b>${N(x.price*100,1)}¢ ${x.you?'<small>YOU</small>':''}</b><span>${N(x.size,1)}</span><span>$${N(x.size*x.price)}</span></button>`;const spread=bids.length&&asks.length?Math.max(0,(asks[0].price-bids[0].price)*100):null;
 surface.innerHTML=`${showDepth?depthChart(bids,asks):''}<div class="order-row order-label"><span>Price</span><span>Shares</span><span>Total</span></div>${asks.slice(0,7).reverse().map(x=>row(x,'ask')).join('')}<div class="book-mid"><strong>${N(selected.yes*100,1)}¢</strong><span>Spread ${spread===null?'—':N(spread,1)+'¢'}</span><span><i class="live-dot"></i> ${T(lastTick||Date.now())}</span></div>${bids.slice(0,7).map(x=>row(x,'bid')).join('')}`;
}
function depthChart(bids,asks){const max=Math.max(1,bids.reduce((a,b)=>a+b.size,0),asks.reduce((a,b)=>a+b.size,0));function path(rows,right){let sum=0;return rows.slice(0,15).map((r,i)=>{sum+=r.size;return `${i?'L':'M'}${250+(right?1:-1)*(i+1)*14},${120-sum/max*100}`;}).join(' ');}return `<svg class="depth-chart" viewBox="0 0 500 140" role="img" aria-label="Order book depth"><path d="M250,120 ${path(bids,false).replace('M','L')} L40,120Z" fill="#e0f4ec" stroke="#159a72"/><path d="M250,120 ${path(asks,true).replace('M','L')} L460,120Z" fill="#fce5e9" stroke="#dc6678"/></svg>`;}
function socialPage(){const tabs=[['for-you','For you'],['following','Following'],['news','News'],['ideas','Market ideas'],['saved','Saved']];return `<div class="container social-container"><div class="page-heading"><h1>Social</h1><div>${B('connections',I('link')+' Connections','button secondary')}${B('compose',I('plus')+' New post','button primary')}</div></div><div class="social-layout"><section class="social-main"><nav class="social-tabs" aria-label="Social feed">${tabs.map(([v,l])=>`<a href="#social/${v}" class="${feedTab===v?'active':''}">${l}</a>`).join('')}</nav>${feedTab==='news'?newsFeed():feedTab==='ideas'?ideasFeed():`<button class="feed-composer" data-action="compose">${avatar('you','small')}<span>What’s your market thesis?</span>${I('plus')}</button><div id="social-feed">${socialFeed()}</div>`}</section><aside class="social-rail"><section class="rail-card"><div class="section-heading compact-heading"><h3>Your circle</h3><a href="#traders">Explore ${I('chevron')}</a></div>${people.slice(0,5).map(p=>`<div class="person-row"><button data-action="profile" data-id="${p.id}" class="person-profile">${avatar(p.id,'small')}<span><b>${E(p.name)}</b><small>${E(p.niche)}</small></span></button>${B('follow',I(s.following.includes(p.id)?'check':'plus'),'follow-button '+(s.following.includes(p.id)?'following':''),`data-id="${p.id}" aria-label="${s.following.includes(p.id)?'Unfollow':'Follow'} ${E(p.name)}"`)}</div>`).join('')}</section><section class="rail-card"><div class="section-heading compact-heading"><h3>What’s moving</h3>${I('bolt')}</div>${events.filter(e=>e.volume24).sort((a,b)=>b.volume24-a.volume24).slice(0,4).map((e,i)=>`<a href="#market/${e.id}/${e.markets[0].id}" class="moving-market"><span>0${i+1}</span><div><b>${E(e.title)}</b><small>$${C(e.volume24)} today</small></div></a>`).join('')}</section><section class="rail-card market-ideas-teaser"><span class="reward-emblem">${I('spark')}</span><h3>A question worth a market?</h3><p>Put it to the community.</p>${B('compose-idea','Suggest a market '+I('arrow'),'text-link')}</section></aside></div></div>`;}
function socialFeed(){let list=s.posts;if(feedTab==='following')list=list.filter(p=>s.following.includes(p.person)||p.person==='you');if(feedTab==='saved')list=list.filter(p=>s.savedPosts.includes(p.id));return list.length?[...list].sort((a,b)=>b.time-a.time).map(p=>postMarkup(p)).join(''):empty(feedTab==='following'?'Build your circle':'Nothing saved yet',feedTab==='following'?'Follow traders to see their theses and entries here.':'Save a thesis to revisit it later.','find-traders','Explore traders');}
function postMarkup(p,full=false){const user=person(p.person),e=byId(p.eventId),m=e?.markets.find(m=>m.id===p.marketId)||e?.markets[0];return `<article class="social-post" id="post-${p.id}"><div class="post-heading"><button class="avatar-button" data-action="profile" data-id="${user.id}" aria-label="View ${E(user.name)}">${avatar(user.id)}</button><div><button class="name-button" data-action="profile" data-id="${user.id}">${E(user.name)}${user.id!=='you'?'<span class="verified-dot">✓</span>':''}</button><span>${E(user.handle)} · ${ago(p.time)}</span></div>${B('save-post',I('bookmark'),'icon-button '+(s.savedPosts.includes(p.id)?'saved':''),`data-id="${p.id}" aria-label="Save thesis"`)}</div>${p.kind==='trade'?`<div class="trade-post-line"><span class="position-tag ${p.side?.toLowerCase()}">${p.side?.toUpperCase()}</span><b>Bought $${N(p.amount,0)} at ${N(p.price*100,1)}¢</b></div>`:''}${p.text?`<p class="post-text">${E(p.text)}</p>`:''}${m?`<a href="#market/${e.id}/${m.id}" class="attached-market">${picture(e)}<div><span>${E(e.category)}</span><strong>${E(m.question||e.title)}</strong></div><b data-prob="${m.id}">${P(m.yes)}<small>%</small></b></a>`:''}${p.kind==='thesis'&&m?`<div class="thesis-conviction"><span>My view</span><b class="${p.side==='No'?'red':'green'}">${p.conviction}% ${E(outcomeLabel(m,p.side||'Yes'))}</b></div>`:''}<div class="post-actions">${B('like-post',I('heart')+' '+((p.likes||0)+(s.postLikes.includes(p.id)?1:0)),s.postLikes.includes(p.id)?'liked':'',`data-id="${p.id}" aria-label="Like thesis"`)}${B('post-thread',I('chat')+' '+((p.replies||[]).length),'',`data-id="${p.id}" aria-label="Open discussion"`)}${B('repost',I('repost')+' '+(p.reposts||0),'',`data-id="${p.id}" aria-label="Repost thesis"`)}${B('share-post',I('share'),'post-share',`data-id="${p.id}" aria-label="Share thesis"`)}</div>${full?`<div class="thread-replies">${(p.replies||[]).map(c=>commentMarkup(c,true)).join('')}<form id="post-reply-form" data-id="${p.id}"><input id="post-reply" aria-label="Reply to thesis" placeholder="Add your perspective…" required maxlength="1000"><button class="button primary small-button">Reply</button></form></div>`:''}</article>`;}
function newsFeed(){const list=newsFilter==='All'?news:news.filter(n=>n.category===newsFilter);return `<div class="news-feed-toolbar"><h2>The briefing</h2><div class="news-chips">${['All','Crypto','World','Economy','Tech & AI'].map(c=>B('news-filter',c,newsFilter===c?'selected':'',`data-category="${c}"`)).join('')}</div></div>${list.length?list.map(n=>`<article class="news-feed-item"><div class="news-source">${E(n.publisher)}<span>${ago(n.time)}</span><span>${E(n.category)}</span></div><button data-action="news" data-id="${n.id}" class="news-headline">${E(n.title)}</button>${n.summary?`<p>${E(n.summary)}</p>`:''}<div>${B('news','Read story '+I('arrow'),'text-link',`data-id="${n.id}"`)}${B('discuss-news',I('chat')+' Discuss','text-button',`data-id="${n.id}"`)}</div></article>`).join(''):'<div class="quiet-empty">The latest headlines are loading.</div>'}`;}
function ideasFeed(){const list=[...s.proposals,...ideas].sort((a,b)=>(b.votes+(s.ideaVotes.includes(b.id)?1:0))-(a.votes+(s.ideaVotes.includes(a.id)?1:0)));return `<div class="ideas-intro"><div><h2>What should we predict next?</h2><p>Suggest a question. Help the best ideas rise.</p></div>${B('compose-idea','Suggest market '+I('plus'),'button primary')}</div>${list.map(p=>`<article class="idea-card"><button class="idea-vote ${s.ideaVotes.includes(p.id)?'voted':''}" data-action="vote-idea" data-id="${p.id}" aria-label="Vote for ${E(p.title)}">${I('trend')}<b>${p.votes+(s.ideaVotes.includes(p.id)?1:0)}</b></button><div><div class="idea-meta">${avatar(p.person,'tiny')}<b>${E(person(p.person).name)}</b><span>${E(p.category)}</span><time>${ago(p.time)}</time></div><h3>${E(p.title)}</h3><p>${E(p.text)}</p><div class="idea-footer"><span>Community review</span>${B('idea-discuss','Discuss idea '+I('chat'),'text-button',`data-id="${p.id}"`)}</div></div></article>`).join('')}`;}
function tradersPage(){const ranking=rankPeople(leaderPeriod,leaderMetric);return `<div class="container traders-container"><div class="page-heading"><h1>Traders</h1><a href="#social/following" class="button secondary">Your circle ${I('users')}</a></div><div class="leaderboard-heading"><h2>Leaderboard</h2><div class="leaderboard-controls"><div class="segmented" aria-label="Leaderboard period">${[['day','Today'],['month','This month'],['all','All time']].map(([v,l])=>B('leader-period',l,leaderPeriod===v?'active':'',`data-value="${v}"`)).join('')}</div><select id="leader-metric" aria-label="Leaderboard ranking"><option value="profit" ${leaderMetric==='profit'?'selected':''}>Profit</option><option value="volume" ${leaderMetric==='volume'?'selected':''}>Volume</option><option value="winrate" ${leaderMetric==='winrate'?'selected':''}>Win rate</option></select></div></div><div class="leader-podium">${ranking.slice(0,3).map((p,i)=>`<article class="podium-card"><div><span class="rank-medal rank-${i}">${i+1}</span>${B('follow',I(s.following.includes(p.id)?'check':'plus'),'follow-button',`data-id="${p.id}" aria-label="${s.following.includes(p.id)?'Unfollow':'Follow'} ${E(p.name)}"`)}</div><button class="podium-profile" data-action="profile" data-id="${p.id}">${avatar(p.id)}<strong>${E(p.name)}</strong><span>${E(p.niche)}</span></button><div class="podium-metric ${leaderMetric==='profit'?'green':''}">${leaderMetric==='profit'?'+$'+N(p.profit,0):leaderMetric==='volume'?'$'+C(p.volume):p.winrate+'%'}<small>${leaderMetric==='profit'?'Profit':leaderMetric==='volume'?'Volume':'Win rate'} · ${leaderPeriod==='day'?'today':leaderPeriod==='all'?'all time':'this month'}</small></div></article>`).join('')}</div><section class="leaderboard-table-wrap"><table class="leaderboard-table"><thead><tr><th>Rank</th><th>Trader</th><th>Profit</th><th>Volume</th><th>Win rate</th><th></th></tr></thead><tbody>${ranking.map((p,i)=>`<tr><td><span class="rank-number">${i+1}</span></td><td><button data-action="profile" data-id="${p.id}" class="table-profile">${avatar(p.id,'small')}<span><b>${E(p.name)}</b><small>${E(p.handle)}</small></span></button></td><td class="${p.profit>=0?'green':'red'}">${p.profit>=0?'+':''}$${N(p.profit,0)}</td><td>$${C(p.volume)}</td><td>${p.winrate}%</td><td>${B('follow',s.following.includes(p.id)?'Following':'Follow','button small-button '+(s.following.includes(p.id)?'secondary':'follow-outline'),`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></section><section class="discover-traders"><div class="section-heading"><h2>Find your perspective</h2></div><div class="trader-cards">${people.slice(3,9).map(p=>`<article><button data-action="profile" data-id="${p.id}" class="trader-card-profile">${avatar(p.id)}<b>${E(p.name)}</b><span>${E(p.niche)}</span></button><p>${E(p.bio)}</p>${B('follow',s.following.includes(p.id)?I('check')+' Following':I('plus')+' Follow','button full '+(s.following.includes(p.id)?'secondary':'primary'),`data-id="${p.id}"`)}</article>`).join('')}</div></section></div>`;}
function poolCandidates(){return events.filter(e=>!poolSearch||(e.title+' '+e.category).toLowerCase().includes(poolSearch.toLowerCase())).filter(e=>{const m=e.markets[0];return m.yes>.03&&m.yes<.97;}).slice(0,24);}
function poolsPage(){const deposited=s.liquidity.reduce((a,p)=>a+p.amount,0);const claimable=s.liquidity.reduce((a,p)=>a+makerAccrual(p,campaignFor(byId(p.eventId)||{id:p.marketId})),0);return `<div class="container pools-container"><div class="page-heading"><h1>Liquidity pools</h1><a href="#rewards" class="button secondary">Your rewards ${I('gift')}</a></div><section class="pools-hero"><div><span class="eyebrow">MARKET MAKING</span><h2>Fund a market.<br>Share in the rewards.</h2><p>Choose a market and an amount. Odds quotes both sides for you.</p>${B('pools-how','How it works '+I('arrow'),'text-link')}</div><div class="pool-account"><div><span>Your liquidity</span><strong>$${N(deposited)}</strong></div><div><span>Available rewards</span><strong id="maker-claimable">$${N(claimable,4)}</strong></div>${B('claim-maker','Claim rewards','button primary',claimable<.001?'disabled':'')}</div></section>${s.liquidity.length?`<section class="your-pools"><div class="section-heading"><h2>Your pools</h2></div>${s.liquidity.map(p=>{const e=byId(p.eventId),camp=campaignFor(e||{id:p.marketId});return `<div class="your-pool-row"><div>${e?picture(e):''}<a href="#market/${p.eventId}/${p.marketId}">${E(p.title)}</a></div><span>$${N(p.amount)}<small>Deposited</small></span><span class="green">${quoteQuality(p.spread||3)}%<small>Quote quality</small></span><span>$${N(makerAccrual({...p,claimedAt:Date.now()-86400000},camp))}<small>Estimated / day</small></span>${B('withdraw','Withdraw','button secondary small-button',`data-m="${p.marketId}"`)}</div>`;}).join('')}</section>`:''}<div class="section-heading"><h2>Explore pools</h2><label class="pool-search">${I('search')}<input id="pool-search" type="search" placeholder="Find a market" aria-label="Search pools" value="${E(poolSearch)}"></label></div><div class="pool-grid">${poolCandidates().map(e=>{const m=[...e.markets].sort((a,b)=>Math.abs(.5-a.yes)-Math.abs(.5-b.yes))[0],camp=campaignFor(e);return `<article class="pool-card"><div class="pool-card-heading">${picture(e)}<a href="#market/${e.id}/${m.id}">${E(e.title)}</a></div><div class="pool-card-reward"><span>Daily rewards</span><strong>$${N(camp.daily,0)} <small>USDST</small></strong></div><div class="pool-card-metrics"><span>Spread ≤ ${camp.maxSpread}¢</span><span>From $${camp.minAmount}</span><span>Two-sided quotes</span></div>${B('open-pool','Add liquidity','button secondary full',`data-e="${e.id}" data-m="${m.id}"`)}</article>`;}).join('')}</div></div>`;}
const missions=[['first','Your first prediction','Place a prediction.','bolt',()=>s.predictions>=1],['watch','Keep an eye on it','Save three markets.','bookmark',()=>s.watchlist.length>=3],['follow','Find your circle','Follow two traders.','users',()=>s.following.length>=2],['lp','Make a market','Add liquidity to one market.','droplet',()=>s.liquidity.length>0],['learn','Know the rules','Read a market’s resolution.','info',()=>s.claims.includes('read-rules')]];
function wheel(){return `<div class="wheel-shell"><div class="wheel-pointer"></div><div class="reward-wheel" id="reward-wheel" style="transform:rotate(${wheelAngle}deg)">${['100 XP','25 USDST','250 XP','50 USDST','500 XP','100 USDST'].map((l,i)=>`<span style="--i:${i}"><b>${l}</b></span>`).join('')}<span class="wheel-hub"><img src="assets/icon.png" alt="STRATO Odds"></span></div></div>`;}
function rewardsPage(){const deposited=s.liquidity.reduce((a,p)=>a+p.amount,0),estimated=s.liquidity.reduce((a,p)=>{const c=campaignFor(byId(p.eventId)||{id:p.marketId});return a+makerAccrual({...p,claimedAt:Date.now()-86400000},c);},0);return `<div class="container rewards-container"><div class="page-heading"><h1>Rewards</h1><div class="xp-balance">${I('spark')}<strong>${N(s.xp,0)} XP</strong><span>${s.xp<1000?'Forecaster':'Market insider'}</span></div></div><section class="wheel-feature"><div><span class="eyebrow">THE ODDS WHEEL</span><h2>A little extra<br>for your next call.</h2><p>One spin for every ten predictions.</p><div class="spin-progress-text"><b>${s.predictions%10}/10</b><span>${spins()} ${spins()===1?'spin':'spins'} ready</span></div><div class="progress"><i style="width:${spins()?100:s.predictions%10*10}%"></i></div>${B('spin',spinBusy?'Spinning…':spins()?'Spin the wheel '+I('refresh'):'Make a prediction '+I('arrow'),'button primary full',spinBusy?'disabled':'')}</div>${wheel()}<div class="wheel-rewards-overview"><span>Your rewards</span><strong>$${N(s.rewards.reduce((a,r)=>a+(r.cash||0),0))}</strong><small>USDST collected</small><div class="reward-history-mini">${s.rewards.slice(0,3).map(r=>`<div>${I('gift')}<span>${E(r.label.replace(/demo /g,'').replace(/ · sample referral/,' · referral').replace(/ · model LP fees/,' · liquidity'))}</span></div>`).join('')}</div></div></section><section class="maker-program"><div class="maker-program-intro"><span class="reward-emblem">${I('droplet')}</span><h2>Rewards for better markets.</h2><p>Add liquidity. Keep a tight spread.<br>Earn while your quotes stay active.</p><a href="#pools" class="button primary">Explore liquidity pools ${I('arrow')}</a></div><div class="maker-program-cards"><article><span>Liquidity rewards</span><strong>$${N(estimated)}</strong><small>Your estimated daily share</small></article><article><span>Quote quality</span><strong>${deposited?Math.round(s.liquidity.reduce((a,p)=>a+quoteQuality(p.spread||3),0)/s.liquidity.length):'—'}${deposited?'%':''}</strong><small>Balanced, competitive quotes</small></article><article><span>Your active liquidity</span><strong>$${N(deposited,0)}</strong><small>${s.liquidity.length} ${s.liquidity.length===1?'market':'markets'} supported</small></article></div></section><div class="section-heading"><h2>Starter missions</h2><span>${missions.filter(([id])=>s.claims.includes(id)).length}/${missions.length} completed</span></div><div class="mission-grid">${missions.map(([id,title,desc,ic,test])=>`<article><span class="mission-icon">${I(ic)}</span><div><h3>${title}</h3><p>${desc}</p></div>${s.claims.includes(id)?'<span class="mission-complete">'+I('check')+'</span>':B('mission',test()?'Claim 100 XP':'100 XP','button '+(test()?'primary':'secondary'),`data-id="${id}" ${test()?'':'disabled'}`)}</article>`).join('')}</div><div class="participation-programs"><article><span class="reward-emblem">${I('users')}</span><h3>Bring your circle</h3><p>Earn 50 USDST when a friend makes their first prediction.</p>${B('referral','Invite a friend '+I('arrow'),'text-link')}</article><article><span class="reward-emblem">${I('chat')}</span><h3>Share your research</h3><p>Earn 150 XP for your first market thesis.</p>${B('research-reward',s.claims.includes('creator-thesis')?'Research reward claimed':s.posts.some(p=>p.person==='you'&&p.kind==='thesis')?'Claim 150 XP':'Write a thesis '+I('arrow'),'text-link',s.claims.includes('creator-thesis')?'disabled':'')}</article><article><span class="reward-emblem">${I('trophy')}</span><h3>Build your track record</h3><p>See how your predictions compare with the community.</p><a href="#traders" class="text-link">View leaderboard ${I('arrow')}</a></article></div></div>`;}
function portfolioPage(){const prices=priceMap(),total=portfolioValue(s,prices),pnl=s.positions.reduce((a,p)=>a+p.shares*(prices[p.key]??p.cost/p.shares)-p.cost,0);return `<div class="container portfolio-container"><div class="page-heading"><h1>Portfolio</h1>${B('fund','Add funds '+I('plus'),'button primary')}</div><div class="portfolio-summary"><div><span>Total value</span><strong>$${N(total)}</strong></div><div><span>Available</span><strong>$${N(s.balance)}</strong></div><div><span>Open P&L</span><strong class="${pnl>=0?'green':'red'}">${pnl>=0?'+':''}$${N(pnl)}</strong></div><div><span>Liquidity</span><strong>$${N(s.liquidity.reduce((a,p)=>a+p.amount,0))}</strong></div></div><div class="portfolio-panel"><nav class="detail-tabs">${[['positions','Positions',s.positions.length],['orders','Open orders',s.orders.length],['liquidity','Liquidity',s.liquidity.length],['history','Activity',s.trades.length]].map(([v,l,n])=>B('portfolio-tab',`${l}<span>${n}</span>`,portfolioTab===v?'active':'',`data-tab="${v}"`)).join('')}</nav>${portfolioContent(prices)}</div><div class="portfolio-export">${B('export','Export activity '+I('external'),'text-button')}</div></div>`;}
function portfolioContent(prices){const rows=portfolioTab==='positions'?s.positions:portfolioTab==='orders'?s.orders:portfolioTab==='liquidity'?s.liquidity:s.trades;if(!rows.length)return empty(portfolioTab==='positions'?'Your first position starts here.':portfolioTab==='orders'?'No open orders.':portfolioTab==='liquidity'?'Choose a market to support.':'Your activity will appear here.','',portfolioTab==='liquidity'?'find-pools':'find-markets',portfolioTab==='liquidity'?'Explore pools':'Explore markets');return `<div class="table-scroll"><table class="portfolio-table"><thead><tr><th>Market</th><th>${portfolioTab==='history'?'Action':'Outcome'}</th><th>${portfolioTab==='positions'?'Shares':portfolioTab==='orders'?'Limit':'Amount'}</th><th>${portfolioTab==='positions'?'Value':portfolioTab==='history'?'Time':'Status'}</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><a href="#market/${p.eventId}/${p.marketId}">${E(p.title)}</a></td><td><span class="position-tag ${p.side==='No'?'no':'yes'}">${portfolioTab==='history'?p.type==='lp'?'Liquidity':p.type:p.side||'Liquidity'}</span></td><td>${portfolioTab==='positions'?N(p.shares):portfolioTab==='orders'?N(p.price*100,1)+'¢':'$'+N(p.type==='sell'?p.proceeds:p.amount)}</td><td>${portfolioTab==='positions'?'$'+N(p.shares*(prices[p.key]??p.cost/p.shares)):portfolioTab==='history'?T(p.time):portfolioTab==='orders'?'$'+N(p.amount)+' reserved':'Active'}</td><td>${portfolioTab==='positions'?B('sell-position','Sell','button secondary small-button',`data-key="${p.key}"`):portfolioTab==='orders'?B('cancel-order','Cancel','text-button',`data-id="${p.id}"`):portfolioTab==='liquidity'?B('withdraw','Withdraw','text-button',`data-m="${p.marketId}"`):''}</td></tr>`).join('')}</tbody></table></div>`;}
let returnFocus=null;
function modal(title,body,wide=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${E(title)}" tabindex="-1"><header><h2>${title}</h2>${B('close',I('close'),'icon-button','aria-label="Close dialog"')}</header>${body}</section></div>`;$('.modal').focus();}
function close(){if(spinBusy)return;$('#modal-root').innerHTML='';returnFocus?.focus?.();}
function review(){if(!selected)return;try{const price=mode==='buy'&&orderType==='limit'?Number(limitPrice)/100:side==='Yes'?selected.yes:1-selected.yes;pending={type:mode==='earn'?'lp':mode==='sell'?'sell':orderType==='limit'?'limit':'buy',key:selected.id+'-'+side,eventId:event.id,marketId:selected.id,title:selected.question,side,price,amount:Number(amount),shares:Number(amount)};if(mode==='earn'&&pending.amount<campaignFor(event).minAmount)throw Error('Add at least $'+campaignFor(event).minAmount+' to this pool.');transact(s,pending);modal(mode==='earn'?'Add liquidity':mode==='sell'?'Review sale':orderType==='limit'?'Review limit order':'Review prediction',`<div class="review-market">${picture(event)}<h3>${E(selected.question)}</h3></div><div class="review-outcome"><span class="position-tag ${side.toLowerCase()}">${mode==='earn'?'LIQUIDITY':E(outcomeLabel(selected,side).toUpperCase())}</span><b>${mode==='sell'?N(amount)+' shares':'$'+N(amount)}</b></div><div class="review-calculation">${ticketCalculation()}${mode==='buy'?`<div class="calculation-row"><span>Maximum loss</span><b>$${N(amount)}</b></div>`:''}</div>${mode==='earn'?'<p class="dialog-note">Your funds quote both sides of this market. You can withdraw your available liquidity from Portfolio.</p>':orderType==='limit'?'<p class="dialog-note">Your funds stay reserved until the order fills or you cancel it.</p>':''}${B('confirm-trade',mode==='earn'?'Confirm liquidity':mode==='sell'?'Confirm sale':orderType==='limit'?'Place order':'Confirm prediction','button primary full')}`);}catch(err){notify(err.message);}}
function confirmTrade(){if(!pending)return;try{const a=pending;s=transact(s,a);if(a.type==='lp'){const p=s.liquidity.find(p=>p.marketId===a.marketId);p.spread=spread;p.claimedAt??=p.time;}pending=null;updateAccount();close();if(a.type==='buy'||a.type==='sell')addActivity({...a,person:'you',id:'own-'+Date.now(),time:Date.now(),yes:a.side==='Yes'?a.price:1-a.price,name:'You'});chime(a.type==='lp'?'liquidity':'trade');render();notify(a.type==='lp'?'Liquidity added. Your quotes are active.':a.type==='limit'?'Limit order placed.':a.type==='sell'?'Position sold.':s.predictions%10===0?'Prediction placed. A reward spin is ready.':'Prediction placed. +20 XP');}catch(err){notify(err.message);}}
function composer(kind='thesis',initialText=''){
 const choose=selected?event.id:'';modal(kind==='idea'?'Suggest a market':'New post',`<form id="compose-form"><div class="compose-type segmented"><button type="button" data-action="compose-type" data-kind="thesis" class="${kind==='thesis'?'active':''}">Thesis</button><button type="button" data-action="compose-type" data-kind="note" class="${kind==='note'?'active':''}">Post</button><button type="button" data-action="compose-type" data-kind="idea" class="${kind==='idea'?'active':''}">Market idea</button></div><input type="hidden" name="kind" value="${kind}"><div class="compose-author">${avatar('you','small')}<div><b>You</b><span>Public post</span></div></div>${kind==='idea'?`<label class="field-label">Your market question<input class="text-input" name="title" aria-label="Market question" placeholder="Will…?" maxlength="180" required></label><label class="field-label">Topic<select class="text-input" name="category">${cats.filter(c=>!['Trending','Live'].includes(c)).map(c=>`<option>${c}</option>`).join('')}</select></label>`:''}<textarea class="compose-text" name="text" id="compose-text" aria-label="Write your post" placeholder="${kind==='idea'?'How should this market resolve? What source would you use?':'What’s your thesis? What would change your mind?'}" maxlength="4000" required>${E(initialText)}</textarea>${kind!=='idea'?`<label class="attach-label">${I('link')} Link a market<select name="eventId" id="compose-market" aria-label="Attach market"><option value="">Choose a market</option>${events.map(e=>`<option value="${e.id}" ${choose===e.id?'selected':''}>${E(e.title)}</option>`).join('')}</select></label>${kind==='thesis'?`<div class="compose-position"><label>Your view<select name="side"><option>Yes</option><option>No</option></select></label><label>Conviction <span id="conviction-value">65%</span><input type="range" name="conviction" id="conviction" min="1" max="99" value="65"></label></div>`:''}`:''}<div class="publish-destinations"><span>Also share to</span><label><input type="checkbox" name="x" id="share-x">${I('x')} X</label><label><input type="checkbox" name="instagram" id="share-instagram">${I('instagram')} Instagram</label></div><div class="publish-preview" id="publish-preview" hidden><span>X draft</span><p id="x-draft-preview"></p><small>${xConfig.x?'Connected account · publishes with your post':'X is not connected. Your draft will be prepared for sharing.'}</small></div><div class="compose-footer"><span id="compose-length">${initialText.length}/4000</span><button type="submit" class="button primary">${kind==='idea'?'Submit idea':'Publish post'} ${I('send')}</button></div></form>`,true);
}
function xDraft(p){const e=byId(p.eventId);const suffix=e?'\n\n'+e.title:'';const txt=p.text+suffix;return txt.length<=280?txt:txt.slice(0,277)+'…';}
async function publish(form){const d=new FormData(form),kind=d.get('kind'),text=String(d.get('text')||'').trim();if(!text)return;const now=Date.now(),id=crypto.randomUUID();if(kind==='idea'){s.proposals.unshift({id,person:'you',title:String(d.get('title')||'').trim(),text,category:d.get('category'),votes:0,time:now,replies:[]});save();close();location.hash='social/ideas';render();notify('Market idea submitted.');return;}const eid=String(d.get('eventId')||''),e=byId(eid);if(kind==='thesis'&&!e){notify('Choose a market for your thesis.');return;}const p={id,kind,person:'you',text,eventId:eid,marketId:e?.markets[0]?.id,side:String(d.get('side')||'Yes'),conviction:Number(d.get('conviction')||50),time:now,likes:0,reposts:0,replies:[]};s.posts.unshift(p);if(kind==='thesis'){s.comments[p.marketId]??=[];s.comments[p.marketId].unshift({text,time:now});}const toX=d.get('x'),toIG=d.get('instagram');if(toX||toIG)s.outbox.unshift({postId:id,x:toX?'ready':null,instagram:toIG?'ready':null,text:xDraft(p),time:now});save();close();feedTab='for-you';location.hash='social/for-you';render();notify('Your post is published.');
 if(toX&&xConfig.x){try{const r=await fetch('/api/social/x',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:xDraft(p)})});const result=await r.json();const item=s.outbox.find(o=>o.postId===id);if(result.status==='published'){item.x='published';item.url=result.url;notify('Published to X.');}else{item.x='ready';notify(result.error||'Your X draft is saved.');}save();}catch{notify('Your post is saved. The X draft is ready to retry.');}}
 if((toX&&!xConfig.x)||toIG)sharePost(id);
}
function sharePost(id){const p=s.posts.find(p=>p.id===id);if(!p)return;modal('Share your perspective',`<div class="share-draft">${avatar(p.person,'small')}<p>${E(xDraft(p))}</p></div><div class="share-options"><a class="button secondary" href="https://x.com/intent/post?text=${encodeURIComponent(xDraft(p))}" target="_blank" rel="noopener">${I('x')} Open X draft</a>${B('copy-post',I('link')+' Copy post','button secondary',`data-id="${id}"`)}${B('story-card',I('instagram')+' Create social card','button secondary',`data-id="${id}"`)}</div><div class="share-connection-status"><span>${I('link')} ${xConfig.x?'X connected':'Connect X for automatic publishing'}</span>${B('connections','Manage','text-link')}</div>`);}
