function chartPointer(ev){if(!history.length)return;const svg=$('.probability-chart');if(!svg)return;const bounds=svg.getBoundingClientRect(),width=svg.viewBox.baseVal.width,height=svg.viewBox.baseVal.height,g=geometry(visibleHistory(),width,height,fullScale,range==='live'),x=(ev.clientX-bounds.left)/bounds.width*width;const point=g.coords.reduce((best,p)=>Math.abs(p.x-x)<Math.abs(best.x-x)?p:best,g.coords[0]);const cross=$('#crosshair'),dot=$('#crossdot'),tooltip=$('#chart-tooltip');if(cross){cross.setAttribute('x1',point.x);cross.setAttribute('x2',point.x);cross.setAttribute('opacity',1);}if(dot){dot.setAttribute('cx',point.x);dot.setAttribute('cy',point.y);dot.setAttribute('opacity',1);}if(tooltip){tooltip.hidden=false;tooltip.innerHTML=`<b>${N(point.p*100,1)}%</b><span>${D(point.t*1000)} · ${T(point.t*1000)}</span>`;tooltip.style.left=Math.max(0,Math.min(bounds.width-145,(point.x/width*bounds.width)-60))+'px';tooltip.style.top=Math.max(0,point.y/height*bounds.height-65)+'px';}}
function ingest(data){meta=data;const latest=[...data.events,...conceptsData];latest.forEach(e=>allEvents.set(e.id,e));const groups={};data.events.forEach(e=>(groups[e.category]??=[]).push(e));const mixed=[];for(let i=0;i<Math.max(0,...Object.values(groups).map(v=>v.length));i++)for(const c of cats.filter(c=>!['Trending','Live'].includes(c)))if(groups[c]?.[i])mixed.push(groups[c][i]);events=[...mixed.slice(0,8),...conceptsData.slice(0,2),...mixed.slice(8,17),...conceptsData.slice(2,5),...mixed.slice(17),...conceptsData.slice(5)];if(!s.communityReady){s.posts=seedCommunity(events);s.communityReady=true;save();}if(page==='market'&&selected){const old=selected;event=byId(event.id)||event;selected=event.markets.find(m=>m.id===old.id)||old;}}
