async function lookupMarket(id){if(!id||marketLookups.has(id))return;marketLookups.set(id,{pending:true});try{const response=await fetch('/api/event?'+new URLSearchParams({id})),data=await response.json();marketLookups.set(id,{...data,pending:false});if(data.event)allEvents.set(id,data.event);if(page==='market'&&location.hash.split('/')[1]===id){if(data.event)route(false);else render();}}catch{marketLookups.set(id,{pending:false});if(page==='market')render();}}
function openTrade(eid,mid,newSide='Yes',newMode='buy'){const hash='#market/'+eid+'/'+mid;if(location.hash===hash){side=newSide;mode=newMode;render();return;}location.hash=hash;setTimeout(()=>{side=newSide;mode=newMode;amount=newMode==='sell'?(s.positions.find(p=>p.key===mid+'-'+newSide)?.shares||0):25;render();},0);}
async function spin(){if(spinBusy)return;if(!spins()){location.hash='markets';return;}const r=new Uint32Array(1);crypto.getRandomValues(r);const segment=Math.floor(r[0]/4294967296*6);try{s=transact(s,{type:'spin',segment});save();}catch(err){notify(err.message);return;}spinBusy=true;const target=360-segment*60-30;wheelAngle=Math.floor(wheelAngle/360)*360+2160+target;const wheel=$('#reward-wheel');if(wheel)wheel.style.transform=`rotate(${wheelAngle}deg)`;const button=$('[data-action="spin"]');if(button){button.disabled=true;button.textContent='Spinning…';}setTimeout(()=>{spinBusy=false;chime('win');render();const reward=s.rewards[0];modal('Your reward',`<div class="win-result">${I('gift')}<span>THE ODDS WHEEL</span><strong>${E(reward.label.replace('demo ',''))}</strong><p>${reward.cash?'Added to your balance.':'Added to your XP.'}</p>${B('close','Keep going','button primary full')}</div>`);},4300);}
function follow(id){s.following=s.following.includes(id)?s.following.filter(x=>x!==id):[...s.following,id];save();}
function exportAccount(){const url=URL.createObjectURL(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),account:s},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='STRATO-Odds-Account.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function socialCard(id){const p=s.posts.find(p=>p.id===id);if(!p)return;const e=byId(p.eventId);const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#fafbfd';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#001b71';ctx.fillRect(0,0,1080,180);const logo=new Image();logo.src='assets/odds.png';await logo.decode();ctx.drawImage(logo,70,65,360,360*logo.height/logo.width);ctx.fillStyle='#3452ff';ctx.font='600 25px Inter';ctx.fillText('MARKET THESIS',70,260);ctx.fillStyle='#0b1330';ctx.font='600 54px Inter';let y=355;function wrap(text,font,line,max=10){ctx.font=font;let row='',count=0;for(const w of text.split(/\s+/)){const next=row?row+' '+w:w;if(ctx.measureText(next).width>930){ctx.fillText(row,70,y);y+=line;row=w;if(++count>=max)break;}else row=next;}if(row&&count<max){ctx.fillText(row,70,y);y+=line;}}wrap(e?.title||'A market perspective','600 54px Inter',68,4);y+=40;ctx.fillStyle='#4f5e7d';wrap(p.text,'400 34px Inter',53,9);ctx.fillStyle='#001b71';ctx.font='600 28px Inter';ctx.fillText(person(p.person).name,70,1230);ctx.fillStyle='#6b7597';ctx.font='400 24px Inter';ctx.fillText(person(p.person).handle,70,1270);const url=canvas.toDataURL('image/png');modal('Your social card',`<img class="social-card-preview" src="${url}" alt="Market thesis social card"><a class="button primary full" href="${url}" download="STRATO-Odds-Thesis.png">Download card ${I('external')}</a>`);}
function showThread(id){const p=s.posts.find(p=>p.id===id);if(!p)return;if(p.person!=='you'&&!p.replies.length){p.replies=[{id:id+'-r1',person:'leo',text:'The invalidation is the useful part. I’d like to see the next official update before changing the size.',time:p.time+120000,likes:4,replies:[]},{id:id+'-r2',person:'maya',text:'Interesting angle. I’m watching the same market from the other side.',time:p.time+300000,likes:2,replies:[]},{id:id+'-r3',person:'elena',text:'What entry price would change the trade for you?',time:p.time+480000,likes:6,replies:[]}];save();}focusedPost=id;modal('Discussion',postMarkup(p,true),true);}
function draftPreview(){const el=$('#x-draft-preview'),txt=$('#compose-text');if(!el||!txt)return;const f=$('#compose-form');const eid=f.elements.eventId?.value;el.textContent=xDraft({text:txt.value,eventId:eid});$('#publish-preview').hidden=!$('#share-x')?.checked;}
function referral(){modal('Bring your circle',`<div class="referral-icon">${I('users')}</div><h3 class="referral-title">Good markets need good people.</h3><p class="dialog-note">Earn 50 USDST when a friend makes their first prediction.</p><div class="invite-code"><span>ODDS-YOUR-CIRCLE</span>${B('copy-invite',I('link'),'icon-button','aria-label="Copy invite code"')}</div><div class="referral-history"><b>${s.referrals?.length||0}</b><span>friends invited</span></div><details class="build-controls"><summary>Test the invitation flow</summary><label class="field-label">Friend’s name<input class="text-input" id="referral-name" aria-label="Friend name" placeholder="Alex"></label>${B('referral-qualify','Complete first prediction','button secondary full')}</details>`);}
function poolsHelp(){modal('Add liquidity',`<div class="help-step"><b>1</b><div><h3>Choose a market</h3><p>Each pool has its own reward allocation.</p></div></div><div class="help-step"><b>2</b><div><h3>Choose an amount</h3><p>Odds uses it to maintain buy and sell quotes on both sides.</p></div></div><div class="help-step"><b>3</b><div><h3>Earn as you participate</h3><p>Rewards build over time while your quotes meet the market’s size and spread requirements. Your share and quote quality are visible in Pools.</p></div></div><div class="help-step"><b>4</b><div><h3>Stay in control</h3><p>Review the market’s rules, inventory and available liquidity before withdrawing. Returns depend on market activity and are not guaranteed.</p></div></div>${B('close','Got it','button primary full')}`);}
$('#app').addEventListener('input',e=>{const el=e.target;if(el.id==='search'){search=el.value;limit=18;if(page!=='markets'){page='markets';location.hash='markets';}render();}if(el.id==='amount'){amount=Number(el.value);$('#ticket-calculation').innerHTML=ticketCalculation();}if(el.id==='limit-price'){limitPrice=Number(el.value);$('#ticket-calculation').innerHTML=ticketCalculation();}if(el.id==='spread'){spread=Number(el.value);$('#spread-label').textContent=spread+'¢';$('#ticket-calculation').innerHTML=ticketCalculation();}if(el.id==='pool-search'){poolSearch=el.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='conviction')$('#conviction-value').textContent=e.target.value+'%';if(e.target.id==='compose-text'){$('#compose-length').textContent=e.target.value.length+'/4000';draftPreview();}if(e.target.id==='sound-volume'){s.soundVolume=Number(e.target.value);save();}});
document.addEventListener('change',e=>{const el=e.target,v=el.value;if(el.id==='sort'){sort=v;render();}if(el.id==='outcome')location.hash='market/'+event.id+'/'+v;if(el.id==='order-type'){orderType=v;render();}if(el.id==='leader-metric'){leaderMetric=v;render();}if(el.id==='marker-filter'){markerFilter=v;paintChart();}if(el.id==='discussion-sort'){discussionSort=v;$('#detail-panel').innerHTML=detailPanel();}if(['compose-market','share-x'].includes(el.id))draftPreview();});
document.addEventListener('submit',e=>{if(e.target.id==='compose-form'){e.preventDefault();publish(e.target);}if(e.target.id==='discussion-form'){e.preventDefault();const text=$('#discussion-text').value.trim();if(!text)return;s.discussion[selected.id]??=initialComments(selected);s.discussion[selected.id].unshift({id:crypto.randomUUID(),person:'you',text,side:s.positions.find(p=>p.marketId===selected.id)?.side,time:Date.now(),likes:0,replies:[]});save();discussionSort='new';$('#detail-panel').innerHTML=detailPanel();notify('Comment posted.');}if(e.target.id==='reply-form'){e.preventDefault();const c=(s.discussion[selected.id]||[]).find(c=>c.id===e.target.dataset.id);const text=$('#reply-text').value.trim();if(!c||!text)return;(c.replies??=[]).push({id:crypto.randomUUID(),person:'you',text,time:Date.now()});save();close();$('#detail-panel').innerHTML=detailPanel();}if(e.target.id==='post-reply-form'){e.preventDefault();const p=s.posts.find(p=>p.id===e.target.dataset.id),text=$('#post-reply').value.trim();if(!p||!text)return;p.replies.push({id:crypto.randomUUID(),person:'you',text,time:Date.now(),likes:0,replies:[]});save();showThread(p.id);}});
document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-action]');if(!target)return;if(spinBusy){e.preventDefault();return;}const a=target.dataset.action,d=target.dataset;
 if(a==='close')close();
 else if(a==='menu'){menuOpen=!menuOpen;render();}
 else if(a==='menu-close'){menuOpen=false;render();}
 else if(a==='fund')fund();
 else if(a==='fund-confirm'){const n=Number($('#fund-amount').value);if(!Number.isFinite(n)||n<1||n>100000)return notify('Choose an amount between $1 and $100,000.');s.balance+=n;updateAccount();close();render();notify('Funds added.');}
 else if(a==='sound'){s.sound=!s.sound;save();if(s.sound)playSound('trade',s.soundVolume);render();}
 else if(a==='settings')settings();
 else if(a==='settings-sound'){s.sound=!s.sound;save();if(s.sound)chime();settings();}
 else if(a==='settings-stream'){s.stream=!s.stream;save();settings();}
 else if(a==='preview-trade')playSound('trade',s.soundVolume);
 else if(a==='preview-win')playSound('win',s.soundVolume);
 else if(a==='connections')connections();
 else if(a==='x-setup')modal('Connect X',`<div class="about-copy"><p>Automatic publishing uses an X account token with posting permission. Set <code>STRATO_X_USER_TOKEN</code> in the local server environment, then restart the server. Tokens stay on the server and are never exposed in this browser.</p><p>Publishing remains opt-in for each post. Without a token, “Open X draft” opens your post in X for review.</p><a class="text-link" href="https://docs.x.com/x-api/posts/create-post" target="_blank" rel="noopener">X publishing documentation ${I('external')}</a></div>`);
 else if(a==='about')about();
 else if(a==='help'||a==='rules-help')help();
 else if(a==='watch'){s.watchlist=s.watchlist.includes(d.id)?s.watchlist.filter(x=>x!==d.id):[...s.watchlist,d.id];save();render();}
 else if(a==='watch-filter'){watchOnly=!watchOnly;render();}
 else if(a==='clear-search'){search='';watchOnly=false;category='Trending';location.hash='markets';render();}
 else if(a==='more'){limit+=18;const grid=$('.market-grid');grid.innerHTML=filterMarkets().slice(0,limit).map(card).join('');if(filterMarkets().length<=limit)target.remove();}
 else if(a==='open-trade')openTrade(d.e,d.m,d.side);
 else if(a==='open-pool')openTrade(d.e,d.m,'Yes','earn');
 else if(a==='earn-market'){mode='earn';amount=100;render();if(innerWidth<800)$('.ticket-stack').scrollIntoView({behavior:'smooth',block:'start'});}
 else if(a==='mode'){mode=d.mode;amount=mode==='sell'?(s.positions.find(p=>p.key===selected.id+'-'+side)?.shares||0):mode==='earn'?100:25;render();}
 else if(a==='side'){side=d.side;if(mode==='sell')amount=s.positions.find(p=>p.key===selected.id+'-'+side)?.shares||0;render();}
 else if(a==='preset'){amount=mode==='sell'?(s.positions.find(p=>p.key===selected.id+'-'+side)?.shares||0)*Number(d.n):Number(d.n);$('#amount').value=amount;$('#ticket-calculation').innerHTML=ticketCalculation();}
 else if(a==='max'){amount=s.balance;$('#amount').value=amount;$('#ticket-calculation').innerHTML=ticketCalculation();}
 else if(a==='review')review();
 else if(a==='confirm-trade')confirmTrade();
 else if(a==='range'){range=d.range;loadMarket();$$('.timeframes button').forEach(b=>b.classList.toggle('active',b.dataset.range===range));}
 else if(a==='marker-toggle'){markerFilter=markerFilter==='off'?'all':'off';render();}
 else if(a==='full-scale'){fullScale=!fullScale;paintChart();target.textContent=fullScale?'0–100%':'Auto scale';}
 else if(a==='detail-tab'){tab=d.tab;$$('.detail-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#detail-panel').innerHTML=detailPanel();paintBook();}
 else if(a==='refresh-book')pollMarket();
 else if(a==='depth-toggle'){showDepth=!showDepth;target.textContent=showDepth?'Table':'Depth';paintBook();}
 else if(a==='book-price'){mode='buy';orderType='limit';side='Yes';limitPrice=Math.max(1,Math.min(99,Math.round(Number(d.price)*100)));render();if(innerWidth<800)$('.ticket-stack').scrollIntoView({behavior:'smooth'});}
 else if(a==='rules')showRules();
 else if(a==='read-rules'){if(!s.claims.includes('read-rules'))s.claims.push('read-rules');save();close();notify('Market rules read.');}
 else if(a==='alert')alertDialog();
 else if(a==='alert-save'){const value=Number($('#alert-target').value)/100;if(!Number.isFinite(value)||value<=0||value>=1)return notify('Choose a probability from 1% to 99%.');s.alerts.push({marketId:selected.id,title:selected.question,target:value,direction:$('#alert-direction').value,triggered:false});save();close();notify('Price alert saved.');}
 else if(a==='follow'){follow(d.id);if(d.profile)showProfile(d.id);else if($('.modal')){target.textContent=s.following.includes(d.id)?'Following':'Follow';}else render();}
 else if(a==='profile')showProfile(d.id);
 else if(a==='entry')showEntry(d.id);
 else if(a==='entries'){const list=s.socialActivity.filter(a=>a.marketId===selected.id);modal('Trader entries',list.length?list.map(a=>`<div class="entry-list-row"><button data-action="profile" data-id="${a.person}">${avatar(a.person,'small')}<b>${E(person(a.person).name)}</b></button>${activityCard(a)}</div>`).join(''):'<p class="dialog-note">Entries will appear on the chart as traders take positions.</p>',true);}
 else if(a==='entry-trade'){const entry=s.socialActivity.find(a=>a.id===d.id);close();if(entry)openTrade(entry.eventId,entry.marketId,entry.side);}
 else if(a==='comment-like'){s.discussion[selected.id]??=initialComments(selected);const c=s.discussion[selected.id].find(c=>c.id===d.id);if(c){const yes=s.postLikes.includes(c.id);c.likes=(c.likes||0)+(yes?-1:1);s.postLikes=yes?s.postLikes.filter(x=>x!==c.id):[...s.postLikes,c.id];save();$('#detail-panel').innerHTML=detailPanel();}}
 else if(a==='reply'){s.discussion[selected.id]??=initialComments(selected);const c=s.discussion[selected.id].find(c=>c.id===d.id);if(c)modal('Reply to '+E(person(c.person).name),`<p class="quoted-comment">${E(c.text)}</p><form id="reply-form" data-id="${c.id}"><textarea class="compose-text" id="reply-text" aria-label="Write a reply" placeholder="Add your perspective…" required maxlength="1000"></textarea><button class="button primary full" type="submit">Reply</button></form>`);}
 else if(a==='compose')composer('thesis');
 else if(a==='compose-idea')composer('idea');
 else if(a==='compose-type')composer(d.kind,$('#compose-text')?.value||'');
 else if(a==='like-post'){s.postLikes=s.postLikes.includes(d.id)?s.postLikes.filter(x=>x!==d.id):[...s.postLikes,d.id];save();if($('.modal'))showThread(d.id);else render();}
 else if(a==='save-post'){s.savedPosts=s.savedPosts.includes(d.id)?s.savedPosts.filter(x=>x!==d.id):[...s.savedPosts,d.id];save();if($('.modal'))showThread(d.id);else render();}
 else if(a==='repost'){s.reposted??=[];const p=s.posts.find(p=>p.id===d.id);if(p){const undo=s.reposted.includes(d.id);p.reposts=(p.reposts||0)+(undo?-1:1);s.reposted=undo?s.reposted.filter(x=>x!==d.id):[...s.reposted,d.id];save();render();notify(undo?'Repost removed.':'Reposted to your circle.');}}
 else if(a==='post-thread')showThread(d.id);
 else if(a==='share-post')sharePost(d.id);
 else if(a==='copy-post'){const p=s.posts.find(p=>p.id===d.id);if(p){await navigator.clipboard.writeText(xDraft(p));notify('Post copied.');}}
 else if(a==='story-card')socialCard(d.id);
 else if(a==='copy-invite'){await navigator.clipboard.writeText('ODDS-YOUR-CIRCLE');notify('Invite code copied.');}
 else if(a==='news')showNews(d.id);
 else if(a==='news-filter'){newsFilter=d.category;render();}
 else if(a==='discuss-news'){const n=news.find(n=>n.id===d.id);if(n)composer('note',n.title+'\n'+n.url+'\n\n');}
 else if(a==='vote-idea'){s.ideaVotes=s.ideaVotes.includes(d.id)?s.ideaVotes.filter(x=>x!==d.id):[...s.ideaVotes,d.id];save();render();}
 else if(a==='idea-discuss'){const idea=[...s.proposals,...ideas].find(p=>p.id===d.id);if(idea)modal('Market idea',`<h2 class="article-title">${E(idea.title)}</h2><p class="article-summary">${E(idea.text)}</p><form id="idea-reply-form" data-id="${idea.id}"><textarea class="compose-text" name="text" placeholder="How would you resolve this market?" aria-label="Discuss market idea" required maxlength="1000"></textarea><button type="submit" class="button primary full">Add comment</button></form>${(s.ideaReplies?.[idea.id]||[]).map(p=>`<div class="idea-response">${avatar('you','tiny')}<p>${E(p.text)}</p></div>`).join('')}`,true);}
 else if(a==='leader-period'){leaderPeriod=d.value;render();}
 else if(a==='spin')spin();
 else if(a==='mission'){try{s=transact(s,{type:'claim',quest:d.id});save();chime('win');render();notify('Mission complete. +100 XP');}catch(err){notify(err.message);}}
 else if(a==='claim-maker'){try{s=claimMaker(s,p=>campaignFor(byId(p.eventId)||{id:p.marketId}));updateAccount();chime('win');render();notify('Liquidity rewards claimed.');}catch(err){notify(err.message);}}
 else if(a==='pools-how')poolsHelp();
 else if(a==='referral')referral();
 else if(a==='referral-qualify'){try{s=transact(s,{type:'referral',name:$('#referral-name').value});updateAccount();chime('win');referral();notify('First prediction complete. +50 USDST');}catch(err){notify(err.message);}}
 else if(a==='research-reward'){if(!s.posts.some(p=>p.person==='you'&&p.kind==='thesis'))return composer('thesis');try{s=transact(s,{type:'creatorReward'});save();chime('win');render();notify('Research contribution claimed. +150 XP');}catch(err){notify(err.message);}}
 else if(a==='portfolio-tab'){portfolioTab=d.tab;render();}
 else if(a==='cancel-order'){s=cancelOrder(s,d.id);updateAccount();render();notify('Order canceled. Funds returned.');}
 else if(a==='sell-position'){const p=s.positions.find(p=>p.key===d.key);if(p)openTrade(p.eventId,p.marketId,p.side,'sell');}
 else if(a==='withdraw'){try{const p=s.liquidity.find(p=>p.marketId===d.m);const settled=settleMakerPosition(s,d.m,campaignFor(byId(p?.eventId)||{id:d.m}));s=transact(settled,{type:'withdrawLP',marketId:d.m});updateAccount();chime('liquidity');render();notify('Liquidity withdrawn.');}catch(err){notify(err.message);}}
 else if(a==='share-market'){modal('Share market',`<h3>${E(selected.question)}</h3><div class="share-options">${B('compose','Write a thesis','button primary')}${B('copy-market','Copy link','button secondary')}</div>`);}
 else if(a==='copy-market'){await navigator.clipboard.writeText(location.href);notify('Market link copied.');}
 else if(a==='find-traders')location.hash='traders';
 else if(a==='find-pools')location.hash='pools';
 else if(a==='find-markets')location.hash='markets';
 else if(a==='settle'){try{s=transact(s,{type:'settle',marketId:$('#settle-market').value,winning:$('#settle-side').value});updateAccount();close();render();notify('Position settled.');}catch(err){notify(err.message);}}
 else if(a==='reset-confirm')modal('Reset local account?',`<p class="dialog-note">This resets your balance, positions, posts, follows and rewards in this browser.</p>${B('reset','Reset account','button danger full')}`);
 else if(a==='reset'){s={...initialState(),...structuredClone(extra)};s.posts=seedCommunity(events);s.communityReady=true;save();close();render();notify('Account reset.');}
 else if(a==='export')exportAccount();
});
document.addEventListener('submit',e=>{if(e.target.id==='idea-reply-form'){e.preventDefault();const text=new FormData(e.target).get('text');if(!String(text).trim())return;s.ideaReplies??={};(s.ideaReplies[e.target.dataset.id]??=[]).unshift({text:String(text).trim(),time:Date.now()});save();close();notify('Comment added to the market idea.');}});
document.addEventListener('pointermove',e=>{if(e.target.closest('#chart-frame'))chartPointer(e);});
document.addEventListener('pointerout',e=>{if(e.target.closest('#chart-frame')&&!e.relatedTarget?.closest?.('#chart-frame')){$('#chart-tooltip')?.setAttribute('hidden','');$('#crosshair')?.setAttribute('opacity','0');$('#crossdot')?.setAttribute('opacity','0');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))close();else if(menuOpen){menuOpen=false;render();}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search')?.focus();}if(['Enter',' '].includes(e.key)&&e.target.matches('.chart-entry')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Tab'&&$('.modal')){const items=$$('.modal button,.modal a[href],.modal input,.modal textarea,.modal select').filter(el=>!el.disabled&&!el.hidden),first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){e.preventDefault();first?.focus();}}});
document.addEventListener('click',e=>{if(e.target.matches('.modal-overlay'))close();});
window.addEventListener('hashchange',()=>route());
setInterval(()=>{if(!document.hidden&&!$('.modal'))pollMarket();},3000);
setInterval(()=>{if(!document.hidden&&!$('.modal')&&!spinBusy)refreshCatalog();},60000);
setInterval(()=>{if(!document.hidden&&page==='market'&&selected?.token)fetch('/api/trades?'+new URLSearchParams({token:selected.token,condition:selected.condition})).then(r=>r.json()).then(rows=>{if(Array.isArray(rows)){publicTrades=rows;if(tab==='activity'&&$('#trades-surface'))$('#trades-surface').innerHTML=tradesMarkup();}}).catch(()=>{});},20000);
setInterval(()=>{if(document.hidden||!s.stream||spinBusy||$('.modal')||!events.length)return;const e=page==='market'&&selected?event:events[Math.floor(Math.random()*Math.min(35,events.length))],m=page==='market'&&selected?selected:e.markets[0],p=person(s.following.length?s.following[Math.floor(Math.random()*s.following.length)]:people[Math.floor(Math.random()*people.length)].id),pickSide=Math.random()>.4?'Yes':'No';const a={id:crypto.randomUUID(),person:p.id,eventId:e.id,marketId:m.id,question:m.question,type:'buy',side:pickSide,price:pickSide==='Yes'?m.yes:1-m.yes,yes:m.yes,amount:[50,125,250,500][Math.floor(Math.random()*4)],time:Date.now()};addActivity(a);if(page==='market'){paintChart();}else if(page==='markets'){const strip=$('.market-pulse-strip');if(strip)strip.outerHTML=followingStrip();}if(page==='social'&&['for-you','following'].includes(feedTab)){s.posts.unshift({...a,kind:'trade',text:'',likes:0,reposts:0,replies:[]});s.posts=s.posts.slice(0,100);save();const feed=$('#social-feed');if(feed&&window.scrollY<250)feed.innerHTML=socialFeed();}},25000);
(async()=>{
 try{const data=await fetch('/snapshot.json').then(r=>r.json());ingest({...data,status:'snapshot'});}catch{}
 try{const data=await fetch('/news-snapshot.json').then(r=>r.json());news=data.articles||[];}catch{}
 route(false);refreshCatalog(false);fetchHero();refreshNews();fetch('/api/social/config').then(r=>r.json()).then(c=>xConfig=c).catch(()=>{});
})();

setInterval(()=>{if(document.hidden||page!=='pools'||$('.modal'))return;const earned=s.liquidity.reduce((sum,p)=>sum+makerAccrual(p,campaignFor(byId(p.eventId)||{id:p.marketId})),0);const label=$('#maker-claimable'),button=$('[data-action="claim-maker"]');if(label)label.textContent='$'+N(earned,4);if(button)button.disabled=earned<.001;},1000);

setInterval(()=>{if(document.hidden||page!=='market'||!selected)return;const label=$('#quote-update'),status=$('#live-status');if(label)label.textContent=lastTick?'Price updated '+(Date.now()-lastTick<2500?'just now':Math.floor((Date.now()-lastTick)/1000)+'s ago'):'';if(lastTick&&Date.now()-lastTick>15000&&status)status.innerHTML='<i class="live-dot reconnecting"></i> Updating';},1000);
